function validate([n, roads]) {
  if (!Number.isInteger(n) || n < 2 || n > 100) return 'n is between 2 and 100.';
  if (!Array.isArray(roads) || roads.length > n * (n - 1) / 2) return 'roads can have at most n * (n - 1) / 2 entries.';
  const seen = new Set();
  for (const road of roads) {
    if (!Array.isArray(road) || road.length !== 2) return 'Each road is a pair [a, b].';
    const [a, b] = road;
    if (!Number.isInteger(a) || !Number.isInteger(b) || a < 0 || b < 0 || a >= n || b >= n) return 'Cities are numbered 0 to n - 1.';
    if (a === b) return 'A road joins two different cities.';
    const key = Math.min(a, b) * n + Math.max(a, b);
    if (seen.has(key)) return 'Each pair of cities has at most one road.';
    seen.add(key);
  }
  return null;
}

