function maximalNetworkRank(n, roads) {
  let best = 0;
  for (let i = 0; i < n; i++)
    for (let j = i + 1; j < n; j++) {
      // Count every road that touches city i or city j.
      const touching = roads.filter(([a, b]) => a === i || b === i || a === j || b === j).length;
      if (touching > best) best = touching;
    }
  return best;
}

