function generate(rand, size) {
  const n = size === 'large' ? 60 + Math.floor(rand() * 41) : 2 + Math.floor(rand() * 6);
  const pairs = [];
  for (let a = 0; a < n; a++) for (let b = a + 1; b < n; b++) pairs.push([a, b]);
  // Shuffle the pairs; a few hub cities are moved to the front so their roads are picked more often.
  for (let i = pairs.length - 1; i > 0; i--) {
    const k = Math.floor(rand() * (i + 1));
    [pairs[i], pairs[k]] = [pairs[k], pairs[i]];
  }
  const hubs = new Set();
  const hubCount = Math.floor(rand() * 4);
  for (let h = 0; h < hubCount; h++) hubs.add(Math.floor(rand() * n));
  const touchesHub = ([a, b]) => hubs.has(a) || hubs.has(b);
  const ordered = [...pairs.filter(touchesHub), ...pairs.filter(p => !touchesHub(p))];
  const limit = size === 'large' ? Math.min(2000, ordered.length) : ordered.length;
  const count = Math.floor(rand() * (limit + 1));
  const chosen = rand() < 0.5 ? ordered.slice(0, count) : pairs.slice(0, count);
  // Shuffle the chosen roads and randomly flip their direction.
  for (let i = chosen.length - 1; i > 0; i--) {
    const k = Math.floor(rand() * (i + 1));
    [chosen[i], chosen[k]] = [chosen[k], chosen[i]];
  }
  const roads = chosen.map(([a, b]) => (rand() < 0.5 ? [a, b] : [b, a]));
  return [n, roads];
}
